import { DynamoDBClient, GetItemCommand } from "@aws-sdk/client-dynamodb";
import { getTenantContext } from "tenant-utils";

const dynamodb = new DynamoDBClient({ region: process.env.AWS_REGION });

// Store request origin for CORS headers (set at start of each invocation)
let _requestOrigin = "*";

/**
 * Create HTTP response with dynamic CORS origin matching the request.
 * This is required because API Gateway OPTIONS returns access-control-allow-credentials: true,
 * which means the response must echo the exact origin (not wildcard '*').
 */
const createResponse = (statusCode = 200, body, tenantId = null) => {
  const headers = {
    "Content-Type": "application/json",
    "Access-Control-Allow-Headers": "Content-Type,Authorization,X-Api-Key,Set-Cookie,Cookie,X-Requested-With",
    "Access-Control-Allow-Origin": _requestOrigin,
    "Vary": "Origin",
    "Access-Control-Allow-Methods": "OPTIONS,GET,POST",
    "Access-Control-Allow-Credentials": "true",
    "Cache-Control": "no-cache",
    "X-Content-Type-Options": "nosniff",
  };

  if (tenantId) {
    headers["X-Tenant-Id"] = tenantId;
  }

  return {
    statusCode,
    headers,
    body: typeof body === "string" ? body : JSON.stringify(body),
  };
};

/**
 * Fetch reCAPTCHA Enterprise configuration from amfaConfigs in DDB for the given tenant.
 * Returns: { siteKey, apiKey, projectId }
 *
 * Per-tenant values in DDB take priority; falls back to Lambda environment variables.
 */
const getRecaptchaConfig = async (tenantContext) => {
  try {
    const params = {
      TableName: tenantContext.tableNames.configTable,
      Key: {
        id: { S: tenantContext.tenantId },
        configtype: { S: "amfaConfigs" },
      },
    };
    const result = await dynamodb.send(new GetItemCommand(params));
    if (result.Item?.value?.S) {
      const config = JSON.parse(result.Item.value.S);
      return {
        siteKey: config.recaptcha_key || process.env.RECAPTCHA_KEY || "",
        apiKey: config.recaptcha_api_key || process.env.RECAPTCHA_API_KEY || "",
        projectId: config.recaptcha_project_id || process.env.RECAPTCHA_PROJECT_ID || "",
      };
    }
  } catch (err) {
    console.warn(
      `Failed to fetch recaptcha config from DDB for tenant ${tenantContext.tenantId}:`,
      err.message,
    );
  }
  // Fallback to env vars
  return {
    siteKey: process.env.RECAPTCHA_KEY || "",
    apiKey: process.env.RECAPTCHA_API_KEY || "",
    projectId: process.env.RECAPTCHA_PROJECT_ID || "",
  };
};

/**
 * Call reCAPTCHA Enterprise createAssessment API.
 *
 * @see https://cloud.google.com/recaptcha/docs/create-assessment
 */
const createAssessment = async ({ projectId, apiKey, siteKey, token, expectedAction }) => {
  const url = `https://recaptchaenterprise.googleapis.com/v1/projects/${projectId}/assessments?key=${apiKey}`;

  const response = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      event: {
        token,
        siteKey,
        expectedAction,
      },
    }),
  });

  if (!response.ok) {
    const errorBody = await response.text();
    throw new Error(`createAssessment HTTP ${response.status}: ${errorBody}`);
  }

  return response.json();
};

export const handler = async (event, context, callback) => {
  console.log("verifyrecaptcha event received");

  // Set request origin for CORS response headers
  _requestOrigin = event.headers?.origin || event.headers?.Origin || "*";

  const payload = JSON.parse(event.body);
  try {
    // Extract tenant context from request
    const tenantContext = await getTenantContext(event);
    console.log("Tenant context for recaptcha:", tenantContext.tenantId);

    // Get reCAPTCHA Enterprise config from DDB (per-tenant) or fallback to env vars
    const recaptchaConfig = await getRecaptchaConfig(tenantContext);

    if (!recaptchaConfig.apiKey || !recaptchaConfig.projectId || !recaptchaConfig.siteKey) {
      console.error(
        "reCAPTCHA Enterprise not fully configured for tenant:",
        tenantContext.tenantId,
        { hasApiKey: !!recaptchaConfig.apiKey, hasProjectId: !!recaptchaConfig.projectId, hasSiteKey: !!recaptchaConfig.siteKey },
      );
      return createResponse(
        500,
        { success: false, error: "reCAPTCHA Enterprise not configured" },
        tenantContext.tenantId,
      );
    }

    const expectedAction = payload.action || "LOGIN";

    // Call reCAPTCHA Enterprise createAssessment
    const assessment = await createAssessment({
      projectId: recaptchaConfig.projectId,
      apiKey: recaptchaConfig.apiKey,
      siteKey: recaptchaConfig.siteKey,
      token: payload.token,
      expectedAction,
    });

    console.log("Assessment result:", JSON.stringify(assessment));

    // Check if the token is valid
    if (!assessment.tokenProperties?.valid) {
      console.log(
        `CreateAssessment: token invalid - reason: ${assessment.tokenProperties?.invalidReason}`,
      );
      return createResponse(
        200,
        {
          success: false,
          score: 0,
          reason: assessment.tokenProperties?.invalidReason || "INVALID_TOKEN",
        },
        tenantContext.tenantId,
      );
    }

    // Check if the expected action was executed
    // Note: Some reCAPTCHA client libraries (e.g. react-google-recaptcha-v3 in Enterprise mode)
    // may produce tokens with empty action. We log a warning but don't reject the request,
    // as the token validity and score are the primary indicators.
    if (assessment.tokenProperties.action && assessment.tokenProperties.action !== expectedAction) {
      console.warn(
        `CreateAssessment: action mismatch - expected "${expectedAction}", got "${assessment.tokenProperties.action}"`,
      );
      return createResponse(
        200,
        {
          success: false,
          score: 0,
          reason: "ACTION_MISMATCH",
        },
        tenantContext.tenantId,
      );
    }
    if (!assessment.tokenProperties.action) {
      console.warn(
        `CreateAssessment: token action is empty (expected "${expectedAction}"). Proceeding with score-based check.`,
      );
    }

    // Get the risk score (0.0 = likely bot, 1.0 = likely human)
    const score = assessment.riskAnalysis?.score ?? 0;
    console.log(`reCAPTCHA Enterprise score: ${score} for action: ${expectedAction}`);

    if (assessment.riskAnalysis?.reasons?.length > 0) {
      console.log("Risk reasons:", assessment.riskAnalysis.reasons);
    }

    // Score threshold: 0.5 is Google's recommended default
    const isHuman = score >= 0.5;

    return createResponse(
      200,
      {
        success: isHuman,
        score,
      },
      tenantContext.tenantId,
    );
  } catch (e) {
    console.error("verifyrecaptcha error:", e);

    // Try to get tenant ID for error response
    let tenantId = null;
    try {
      const tenantContext = await getTenantContext(event);
      tenantId = tenantContext.tenantId;
    } catch (tenantError) {
      // ignore
    }

    return createResponse(500, { success: false, error: "Internal verification error" }, tenantId);
  }
};
